// ===== EDIT HERE if your sheet headers differ (case-insensitive, first match wins) =====
const COLS = {
  onboarding: { name:['name','employee','employee name'], dept:['department','dept'], status:['status','onboarding status'] },
  leave:      { name:['employee','name','employee name'], type:['leave type','type'], days:['days','no of days','duration'], status:['status','approval status'] },
  feedback:   { dept:['department','dept'], sentiment:['sentiment','sentiment label'], score:['sentiment score','score'] },
  candidates: { name:['candidate','candidate name','name'], role:['role','position','job title'], score:['match score','ai score','score'], status:['decision','recommendation','status'] },
};
// =========================================================================================
const norm = s => String(s ?? '').trim().toLowerCase();
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pick = (row, names) => { const keys = Object.keys(row); for (const n of names) { const k = keys.find(k => norm(k) === n); if (k !== undefined && String(row[k] ?? '').trim() !== '') return row[k]; } return ''; };
const warnings = [];
function rows(nodeName, label) {
  const out = [];
  let items = [];
  try { items = $(nodeName).all(); } catch (e) { warnings.push(`Could not read "${label}" tab`); return out; }
  for (const it of items) {
    const j = it.json || {};
    if (j.error) { warnings.push(`Could not read "${label}" tab`); continue; }
    if (Object.values(j).some(v => String(v ?? '').trim() !== '')) out.push(j);
  }
  return out;
}
const pct = (a, b) => b ? Math.round((a / b) * 100) : 0;
const num = v => { const n = parseFloat(String(v).replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };

const ob = rows('Read Onboarding', 'Onboarding');
const lv = rows('Read Leave', 'Leave');
const fb = rows('Read Feedback', 'Feedback');
const cd = rows('Read Candidates', 'Candidates');

// Onboarding
const obCount = { completed: 0, progress: 0, pending: 0 };
for (const r of ob) { const s = norm(pick(r, COLS.onboarding.status)); if (s.includes('complete') || s.includes('done')) obCount.completed++; else if (s.includes('progress') || s.includes('ongoing') || s.includes('started')) obCount.progress++; else obCount.pending++; }
// Leave
const lvCount = { approved: 0, pending: 0, rejected: 0 }; let approvedDays = 0; const pendingList = [];
for (const r of lv) {
  const s = norm(pick(r, COLS.leave.status)); const d = num(pick(r, COLS.leave.days));
  if (s.includes('approv')) { lvCount.approved++; approvedDays += d; }
  else if (s.includes('reject') || s.includes('declin') || s.includes('deny')) lvCount.rejected++;
  else { lvCount.pending++; pendingList.push({ name: pick(r, COLS.leave.name), type: pick(r, COLS.leave.type), days: d }); }
}
// Feedback
const fbCount = { positive: 0, neutral: 0, negative: 0 }; const negByDept = {}; let scoreSum = 0, scoreN = 0;
for (const r of fb) {
  const s = norm(pick(r, COLS.feedback.sentiment));
  if (s.startsWith('pos')) fbCount.positive++;
  else if (s.startsWith('neg')) { fbCount.negative++; const d = pick(r, COLS.feedback.dept) || 'Unassigned'; negByDept[d] = (negByDept[d] || 0) + 1; }
  else fbCount.neutral++;
  const sc = pick(r, COLS.feedback.score); if (sc !== '') { scoreSum += num(sc); scoreN++; }
}
const topNegDepts = Object.entries(negByDept).sort((a, b) => b[1] - a[1]).slice(0, 3);
// Candidates
const cdCount = { shortlisted: 0, review: 0, rejected: 0 }; let cScore = 0, cN = 0;
const ranked = cd.map(r => ({ name: pick(r, COLS.candidates.name), role: pick(r, COLS.candidates.role), score: num(pick(r, COLS.candidates.score)), status: norm(pick(r, COLS.candidates.status)) }));
for (const c of ranked) {
  if (c.status.includes('short') || c.status.includes('select') || c.status.includes('accept') || c.status.includes('hire')) cdCount.shortlisted++;
  else if (c.status.includes('reject')) cdCount.rejected++;
  else cdCount.review++;
  if (c.score) { cScore += c.score; cN++; }
}
const topCands = [...ranked].sort((a, b) => b.score - a.score).slice(0, 5);

const now = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'medium', timeStyle: 'short' });
const mode = $('Config').first().json.mode;

// ---------- HTML (no JavaScript: n8n sandboxes scripts in webhook HTML) ----------
const bar = (label, v, total, cls) => `<div class="row"><span class="lab">${esc(label)}</span><span class="track"><i class="${cls}" style="width:${pct(v, total)}%"></i></span><span class="val">${v}</span></div>`;
const kpi = (n, l, sub) => `<div class="kpi"><div class="n">${esc(n)}</div><div class="l">${esc(l)}</div><div class="s">${esc(sub)}</div></div>`;
const obTotal = ob.length, lvTotal = lv.length, fbTotal = fb.length, cdTotal = cd.length;
const html = `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HR Automation Dashboard</title><style>
:root{--bg:#0D1310;--panel:#121814;--line:#213028;--text:#DCE6DE;--muted:#75897E;--accent:#C8FF4D;--warn:#E3C25A;--bad:#E36B5A}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;padding:28px 20px}
.wrap{max-width:1040px;margin:0 auto}h1{font-size:1.5rem;margin:0 0 4px}.sub{color:var(--muted);font-size:12px;margin-bottom:22px}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin-bottom:16px}
.kpi{background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:16px}.kpi .n{font-size:1.9rem;font-weight:700;color:var(--accent)}.kpi .l{font-size:12px;margin-top:2px}.kpi .s{font-size:11px;color:var(--muted);margin-top:6px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px}
.card{background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:18px}.card h2{font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin:0 0 14px;font-weight:500}
.row{display:flex;align-items:center;gap:10px;margin-bottom:10px;font-size:12px}.lab{width:96px;color:var(--muted);flex-shrink:0}.track{flex:1;height:9px;background:var(--line);border-radius:2px;overflow:hidden}.track i{display:block;height:100%;background:var(--accent)}.track i.w{background:var(--warn)}.track i.b{background:var(--bad)}.val{width:34px;text-align:right}
table{width:100%;border-collapse:collapse;font-size:12px}td,th{text-align:left;padding:6px 4px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-weight:500}.empty{color:var(--muted);font-size:12px}
.warn{background:#2a2312;border:1px solid var(--warn);color:var(--warn);padding:10px 14px;border-radius:6px;font-size:12px;margin-bottom:14px}
</style></head><body><div class="wrap">
<h1>HR Automation Dashboard</h1><div class="sub">Live from Google Sheets · updated ${esc(now)} IST</div>
${warnings.length ? `<div class="warn">${[...new Set(warnings)].map(esc).join('<br>')} — check the tab names in the Config node.</div>` : ''}
<div class="kpis">
${kpi(pct(obCount.completed, obTotal) + '%', 'Onboarding complete', `${obCount.completed} of ${obTotal} employees`)}
${kpi(lvCount.pending, 'Leave requests pending', `${lvCount.approved} approved · ${approvedDays} days`)}
${kpi(pct(fbCount.positive, fbTotal) + '%', 'Positive feedback', `${fbTotal} responses${scoreN ? ' · avg score ' + (scoreSum / scoreN).toFixed(2) : ''}`)}
${kpi(cdCount.shortlisted, 'Candidates shortlisted', `${cdTotal} screened${cN ? ' · avg match ' + Math.round(cScore / cN) : ''}`)}
</div><div class="grid">
<div class="card"><h2>Onboarding</h2>${obTotal ? bar('Completed', obCount.completed, obTotal, '') + bar('In progress', obCount.progress, obTotal, 'w') + bar('Pending', obCount.pending, obTotal, 'b') : '<div class="empty">No onboarding records yet.</div>'}</div>
<div class="card"><h2>Leave requests</h2>${lvTotal ? bar('Approved', lvCount.approved, lvTotal, '') + bar('Pending', lvCount.pending, lvTotal, 'w') + bar('Rejected', lvCount.rejected, lvTotal, 'b') : '<div class="empty">No leave requests yet.</div>'}</div>
<div class="card"><h2>Employee sentiment</h2>${fbTotal ? bar('Positive', fbCount.positive, fbTotal, '') + bar('Neutral', fbCount.neutral, fbTotal, 'w') + bar('Negative', fbCount.negative, fbTotal, 'b') + (topNegDepts.length ? `<div class="sub" style="margin:12px 0 0">Most negative: ${topNegDepts.map(([d, n]) => esc(d) + ' (' + n + ')').join(', ')}</div>` : '') : '<div class="empty">No feedback yet.</div>'}</div>
<div class="card"><h2>Resume screening</h2>${cdTotal ? bar('Shortlisted', cdCount.shortlisted, cdTotal, '') + bar('In review', cdCount.review, cdTotal, 'w') + bar('Rejected', cdCount.rejected, cdTotal, 'b') : '<div class="empty">No candidates yet.</div>'}</div>
<div class="card"><h2>Pending leave approvals</h2>${pendingList.length ? '<table><tr><th>Employee</th><th>Type</th><th>Days</th></tr>' + pendingList.slice(0, 6).map(p => `<tr><td>${esc(p.name)}</td><td>${esc(p.type)}</td><td>${p.days || ''}</td></tr>`).join('') + '</table>' : '<div class="empty">Nothing waiting.</div>'}</div>
<div class="card"><h2>Top candidates</h2>${topCands.length ? '<table><tr><th>Name</th><th>Role</th><th>Score</th></tr>' + topCands.map(c => `<tr><td>${esc(c.name)}</td><td>${esc(c.role)}</td><td>${c.score || ''}</td></tr>`).join('') + '</table>' : '<div class="empty">No scored candidates yet.</div>'}</div>
</div></div></body></html>`;

const digest = `*HR daily digest — ${now}*\n• Onboarding: ${obCount.completed}/${obTotal} complete (${pct(obCount.completed, obTotal)}%)\n• Leave: ${lvCount.pending} pending approval, ${lvCount.approved} approved\n• Feedback: ${pct(fbCount.positive, fbTotal)}% positive, ${fbCount.negative} negative\n• Hiring: ${cdCount.shortlisted} shortlisted of ${cdTotal} screened` + (warnings.length ? `\n⚠️ ${[...new Set(warnings)].join('; ')}` : '');

return [{ json: { mode, html, digest } }];
